def build_messages(user_message: str) -> list[dict]:
    reminder = {"role": "system", "content": "Reminder: reply in the same language as the message below."}
    return (
        [{"role": "system", "content": SYSTEM_PROMPT}]
        + FEW_SHOT
        + [reminder, {"role": "user", "content": user_message}]
