def search_active_contracts(query_vec, client_id: str, top_k: int = 5):
    cutoff = "2024-10-09"  # now - 2 years
    results = vector_store.query(
        vector=query_vec,
        top_k=top_k * 5,  # over-fetch in case of post-filtering
        filter={
            "client_id": {"$eq": client_id},
            "status": {"$eq": "active"},
            "effective_date": {"$gte": cutoff},
        },
    )
    return results.matches[:top_k]

