from dataclasses import dataclass

@dataclass
class EvalQuestion:
    question: str
    relevant_doc_ids: set[str]

def retrieval_precision_recall(retrieved_ids: list[str], relevant_ids: set[str]) -> dict:
    retrieved_set = set(retrieved_ids)
    true_positives = retrieved_set & relevant_ids
    precision = len(true_positives) / len(retrieved_set) if retrieved_set else 0.0
    recall = len(true_positives) / len(relevant_ids) if relevant_ids else 0.0
    return {"precision": precision, "recall": recall}

def judge_claim_supported(claim: str, context: str) -> bool:
    judge_prompt = (
        f"Context:\n{context}\n\n"
        f"Claim: {claim}\n"
        "Is this claim fully supported by the context above? Answer YES or NO only."
    )
    verdict = call_judge_model(judge_prompt)
    return verdict.strip().upper().startswith("YES")

def faithfulness_score(answer: str, context: str) -> float:
    claims = split_into_claims(answer)  # e.g. sentence splitter
    if not claims:
        return 1.0
    supported = sum(judge_claim_supported(c, context) for c in claims)
    return supported / len(claims)

def run_eval(eval_set: list[EvalQuestion], rag_pipeline):
    results = []
    for item in eval_set:
        retrieved_ids, context, answer = rag_pipeline(item.question)
        rr = retrieval_precision_recall(retrieved_ids, item.relevant_doc_ids)
        faith = faithfulness_score(answer, context)
        results.append({"question": item.question, **rr, "faithfulness": faith})
    return results

