import json

MAX_ITERATIONS = 6

def run_tool_safely(name: str, raw_args: str) -> dict:
    try:
        args = json.loads(raw_args)
    except json.JSONDecodeError as e:
        return {"success": False, "error": f"Invalid JSON arguments: {e}"}

    try:
        result = execute_tool(name, args)
        return {"success": True, "result": result}
    except ToolDomainError as e:
        return {"success": False, "error": str(e)}
    except Exception as e:
        return {"success": False, "error": f"Unexpected tool failure: {e}"}

def run_agent(messages: list[dict], tools: list[dict]):
    for _ in range(MAX_ITERATIONS):
        response = call_model(messages, tools)
        if not response.tool_calls:
            return response  # model is done, no more tools requested

        messages.append({"role": "assistant", "tool_calls": response.tool_calls})
        for tool_call in response.tool_calls:  # handle ALL calls, not just [0]
            outcome = run_tool_safely(tool_call.name, tool_call.arguments)
            messages.append({
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": json.dumps(outcome),
            })

    raise RuntimeError("Agent exceeded max tool-calling iterations without finishing")

