import uuid
import datetime

TOOL_REGISTRY = {
    "delete_customer_data": {"fn": delete_customer_data, "requires_approval": True},
    "get_customer_profile": {"fn": get_customer_profile, "requires_approval": False},
}

def propose_or_execute(name: str, args: dict, requested_by: str) -> dict:
    entry = TOOL_REGISTRY[name]
    if not entry["requires_approval"]:
        return {"status": "executed", "result": entry["fn"](**args)}

    pending_id = str(uuid.uuid4())
    approval_store.save({
        "id": pending_id,
        "tool": name,
        "args": args,
        "requested_by": requested_by,
        "created_at": datetime.datetime.utcnow().isoformat(),
        "status": "pending",
    })
    return {"status": "pending_approval", "pending_id": pending_id}

def record_decision(pending_id: str, approved: bool, decided_by: str) -> dict:
    record = approval_store.get(pending_id)
    record["status"] = "approved" if approved else "rejected"
    record["decided_by"] = decided_by
    record["decided_at"] = datetime.datetime.utcnow().isoformat()
    approval_store.save(record)

    if not approved:
        return {"status": "rejected", "pending_id": pending_id}

    entry = TOOL_REGISTRY[record["tool"]]
    result = entry["fn"](**record["args"])  # only runs after explicit approval
    return {"status": "executed", "pending_id": pending_id, "result": result}

